let parsed;
try {
  parsed = JSON.parse($json.message?.content ?? '{}');
} catch (e) {
  return [{ json: { action: 'skip' } }];
}

const action = parsed.action;

if (action === 'propose_skill') {
  const kebabName = (parsed.name ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/-+/g, '-')
    .slice(0, 64)
    .replace(/^-|-$/g, '');
  if (!kebabName || !parsed.description || !parsed.reason) {
    return [{ json: { action: 'skip' } }];
  }
  const kind = parsed.kind === 'tool_idea' ? 'tool_idea' : 'instruction';
  if (kind === 'instruction' && !parsed.instructions?.trim()) return [{ json: { action: 'skip' } }];
  if (kind === 'tool_idea' && !parsed.tool_idea_details?.trim()) return [{ json: { action: 'skip' } }];
  return [{ json: {
    action: 'propose_skill',
    kind,
    name: kebabName,
    description: parsed.description,
    reason: parsed.reason,
    instructions: parsed.instructions ?? '',
    tool_idea_details: parsed.tool_idea_details ?? '',
  } }];
}

if (action === 'message_user') {
  if (!parsed.message?.trim()) return [{ json: { action: 'skip' } }];
  return [{ json: { action: 'message_user', message: parsed.message.trim() } }];
}

return [{ json: { action: 'skip' } }];

const message = ($json.message || '').toString();
return [{ json: {
  kind: 'instruction',
  name: ('idle-thought-' + Date.now()).slice(0, 64),
  description: 'A proactive idea Amy had while idle, queued instead of messaged directly because the proactive-message cooldown was active.',
  reason: 'Idle reflection wanted to message the user directly but the messaging cooldown was active.',
  instructions: message,
  tool_idea_details: '',
} }];

const skills = $input.all().map(i => i.json).filter(s => s.name);
const text = skills.length
  ? skills.map(s => `- ${s.name} [${s.kind}, ${s.status}]: ${s.description}`).join('\n')
  : '(no existing skills recorded yet)';
return [{ json: { existingSkillsText: text } }];

const candidate = $('Is Propose Skill').item.json;
const existingSkillsText = $('Format Existing Skills').item.json.existingSkillsText;

let isDuplicate = false;
try {
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://ollama:11434/api/chat',
    body: {
      model: 'qwen3:8b',
      stream: false,
      think: false,
      messages: [
        {
          role: 'system',
          content: "You are checking one new skill proposal for whether it duplicates an existing skill (any status) in substance, even if worded completely differently - judge by the underlying need/gap addressed, not matching words.",
        },
        {
          role: 'user',
          content: `Existing skills:\n${existingSkillsText}\n\nNew candidate proposal:\n${candidate.name}: ${candidate.description}`,
        },
      ],
      format: {
        type: 'object',
        properties: { isDuplicate: { type: 'boolean' } },
        required: ['isDuplicate'],
      },
    },
    json: true,
  });
  const parsed = JSON.parse(data.message?.content ?? '{}');
  isDuplicate = Boolean(parsed.isDuplicate);
} catch (e) {
  // Fail open - a dedup-check hiccup must never silently swallow a
  // genuine proposal, same defensive spirit as onError:
  // continueRegularOutput elsewhere in this project.
  isDuplicate = false;
}

return [{ json: { ...candidate, isDuplicate } }];
